1	/**
2	 * CompanyFinancial — Dashboard financeiro da empresa (Slice 3, R12-R16).
3	 *
4	 * Seções:
5	 *  1. Teto de gasto: configurar limite mensal + barra de progresso colorida.
6	 *  2. Faturamento: CTA se não informado; exibe valor quando declarado.
7	 *  3. BI: ratio custo/hora + custo-%-faturamento; gasto por freela; custo de no-show; flags de concentração.
8	 *  4. Seletor de período: mês atual / mês anterior.
9	 *
10	 * Padrões: useState + useEffect, imports relativos, TS strict, design neo-brutalista empresa.
11	 */
12	
13	import { useState } from 'react';
14	import {
15	  TrendingDown,
16	  AlertTriangle,
17	  BarChart2,
18	  Users,
19	  Clock,
20	  DollarSign,
21	  ChevronDown,
22	  ChevronUp,
23	  Info,
24	} from 'lucide-react';
25	import { useSpendLimit, useFinancialBI } from '../../hooks/useFinancialBI';
26	import { customPeriod, currentMonthPeriod } from '../../services/financialBIService';
27	import type { BIPeriod } from '../../services/financialBIService';
28	import { useToast } from '../../contexts/ToastContext';
29	
30	// ---------------------------------------------------------------------------
31	// Helpers de formatacao
32	// ---------------------------------------------------------------------------
33	
34	function formatBRL(value: number): string {
35	  return value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
36	}
37	
38	function formatHours(h: number): string {
39	  if (h === 0) return '0h';
40	  return `${h.toFixed(1)}h`;
41	}
42	
43	function formatPercent(v: number): string {
44	  return `${v.toFixed(1)}%`;
45	}
46	
47	// Retorna o periodo do mes anterior
48	function previousMonthPeriod(): BIPeriod {
49	  const now = new Date();
50	  const firstOfThisMonth = new Date(now.getFullYear(), now.getMonth(), 1);
51	  const firstOfPrev = new Date(now.getFullYear(), now.getMonth() - 1, 1);
52	  const y = firstOfPrev.getFullYear();
53	  const m = String(firstOfPrev.getMonth() + 1).padStart(2, '0');
54	  const fy = firstOfThisMonth.getFullYear();
55	  const fm = String(firstOfThisMonth.getMonth() + 1).padStart(2, '0');
56	  return customPeriod(`${y}-${m}-01`, `${fy}-${fm}-01`);
57	}
58	
59	function periodLabel(p: BIPeriod): string {
60	  const d = new Date(p.start + 'T12:00:00');
61	  return d.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });
62	}
63	
64	// ---------------------------------------------------------------------------
65	// Subcomponente: SpendLimitCard
66	// ---------------------------------------------------------------------------
67	
68	interface SpendLimitCardProps {
69	  spendLimitAmount: number | null;
70	  accumulatedSpend: number;
71	  loading: boolean;
72	  onSave: (amount: number, thresholds: number[]) => Promise<boolean>;
73	}
74	
75	function SpendLimitCard({ spendLimitAmount, accumulatedSpend, loading, onSave }: SpendLimitCardProps) {
76	  const [editing, setEditing] = useState(false);
77	  const [inputValue, setInputValue] = useState('');
78	  const [saving, setSaving] = useState(false);
79	  const { addToast } = useToast();
80	
81	  const pct = spendLimitAmount && spendLimitAmount > 0
82	    ? Math.min((accumulatedSpend / spendLimitAmount) * 100, 100)
83	    : 0;
84	
85	  const barColor =
86	    pct >= 100
87	      ? 'bg-red-600'
88	      : pct >= 90
89	        ? 'bg-red-400'
90	        : pct >= 80
91	          ? 'bg-yellow-400'
92	          : 'bg-blue-600';
93	
94	  const textColor =
95	    pct >= 100
96	      ? 'text-red-600'
97	      : pct >= 90
98	        ? 'text-red-500'
99	        : pct >= 80
100	          ? 'text-yellow-600'
101	          : 'text-blue-600';
102	
103	  async function handleSave() {
104	    const parsed = parseFloat(inputValue.replace(',', '.'));
105	    if (isNaN(parsed) || parsed <= 0) {
106	      addToast('Informe um valor valido maior que zero.', 'error');
107	      return;
108	    }
109	    setSaving(true);
110	    const ok = await onSave(parsed, [80, 90, 100]);
111	    setSaving(false);
112	    if (ok) {
113	      addToast('Teto de gasto salvo!', 'success');
114	      setEditing(false);
115	      setInputValue('');
116	    } else {
117	      addToast('Erro ao salvar o teto. Tente novamente.', 'error');
118	    }
119	  }
120	
121	  if (loading) {
122	    return (
123	      <div className="bg-white border-2 border-black rounded-2xl p-6 animate-pulse space-y-4">
124	        <div className="h-6 bg-gray-200 rounded-xl w-1/3" />
125	        <div className="h-4 bg-gray-200 rounded-xl w-2/3" />
126	        <div className="h-4 bg-gray-200 rounded-xl w-full" />
127	      </div>
128	    );
129	  }
130	
131	  return (
132	    <div className="bg-white border-2 border-black rounded-2xl p-6 shadow-[6px_6px_0px_0px_rgba(0,0,0,1)]">
133	      <div className="flex items-center justify-between mb-4">
134	        <div className="flex items-center gap-2">
135	          <DollarSign size={20} strokeWidth={3} />
136	          <h2 className="text-xl font-black uppercase">Teto de Gasto Mensal</h2>
137	        </div>
138	        <button
139	          onClick={() => {
140	            setEditing((e) => !e);
141	            setInputValue(spendLimitAmount ? String(spendLimitAmount) : '');
142	          }}
143	          className="text-sm font-black uppercase px-4 py-2 rounded-xl border-2 border-black hover:bg-black hover:text-white transition-colors"
144	          aria-label={editing ? 'Cancelar edicao do teto' : 'Editar teto de gasto'}
145	        >
146	          {editing ? 'Cancelar' : spendLimitAmount ? 'Editar' : 'Configurar'}
147	        </button>
148	      </div>
149	
150	      {editing ? (
151	        <div className="space-y-3">
152	          <label htmlFor="spendLimitInput" className="block text-sm font-black uppercase text-gray-600">
153	            Novo teto mensal (R$)
154	          </label>
155	          <input
156	            id="spendLimitInput"
157	            type="number"
158	            min="1"
159	            step="0.01"
160	            value={inputValue}
161	            onChange={(e) => setInputValue(e.target.value)}
162	            placeholder="Ex: 5000,00"
163	            className="w-full border-2 border-black rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-primary text-lg font-bold tabular-nums"
164	          />
165	          <p className="text-xs text-gray-500 flex items-center gap-1">
166	            <Info size={12} />
167	            Alertas in-app ao atingir 80%, 90% e 100% do teto. WhatsApp em breve.
168	          </p>
169	          <button
170	            onClick={handleSave}
171	            disabled={saving || !inputValue}
172	            className="w-full bg-black hover:bg-primary text-white px-6 py-3 rounded-xl font-black uppercase transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
173	          >
174	            {saving ? 'Salvando...' : 'Salvar Teto'}
175	          </button>
176	        </div>
177	      ) : spendLimitAmount && spendLimitAmount > 0 ? (
178	        <div className="space-y-3">
179	          <div className="flex items-end justify-between">
180	            <div>
181	              <p className="text-xs font-bold uppercase text-gray-500">Gasto acumulado</p>
182	              <p className={`text-2xl font-black tabular-nums ${textColor}`}>{formatBRL(accumulatedSpend)}</p>
183	            </div>
184	            <div className="text-right">
185	              <p className="text-xs font-bold uppercase text-gray-500">Teto</p>
186	              <p className="text-2xl font-black tabular-nums">{formatBRL(spendLimitAmount)}</p>
187	            </div>
188	          </div>
189	          {/* Barra de progresso */}
190	          <div
191	            className="w-full bg-gray-100 border-2 border-black rounded-full h-5 overflow-hidden"
192	            role="progressbar"
193	            aria-valuenow={Math.round(pct)}
194	            aria-valuemin={0}
195	            aria-valuemax={100}
196	            aria-label={`Progresso do teto de gasto: ${Math.round(pct)}%`}
197	          >
198	            <div
199	              className={`h-full rounded-full transition-all ${barColor}`}
200	              style={{ width: `${pct}%` }}
201	            />
202	          </div>
203	          <p className={`text-sm font-bold tabular-nums ${textColor}`}>
204	            {formatPercent(pct)} utilizado
205	            {pct >= 100 && ' — Teto ultrapassado!'}
206	            {pct >= 90 && pct < 100 && ' — Atencao: proximo do limite!'}
207	          </p>
208	          <p className="text-xs text-gray-500 flex items-center gap-1">
209	            <Info size={12} />
210	            Alertas in-app ao atingir 80%, 90% e 100%. WhatsApp em breve.
211	          </p>
212	        </div>
213	      ) : (
214	        <div className="bg-gray-50 border-2 border-dashed border-gray-300 rounded-xl p-4 text-center">
215	          <p className="text-sm text-gray-500 font-bold">Nenhum teto configurado.</p>
216	          <p className="text-xs text-gray-400 mt-1">Configure para receber alertas antes de estourar o orcamento.</p>
217	        </div>
218	      )}
219	    </div>
220	  );
221	}
222	
223	// ---------------------------------------------------------------------------
224	// Subcomponente: RevenueCard
225	// ---------------------------------------------------------------------------
226	
227	interface RevenueCardProps {
228	  monthlyRevenueAmount: number | null;
229	  loading: boolean;
230	  onSave: (amount: number) => Promise<boolean>;
231	}
232	
233	function RevenueCard({ monthlyRevenueAmount, loading, onSave }: RevenueCardProps) {
234	  const [editing, setEditing] = useState(false);
235	  const [inputValue, setInputValue] = useState('');
236	  const [saving, setSaving] = useState(false);
237	  const { addToast } = useToast();
238	
239	  async function handleSave() {
240	    const parsed = parseFloat(inputValue.replace(',', '.'));
241	    if (isNaN(parsed) || parsed < 0) {
242	      addToast('Informe um valor valido (use 0 se nao houve faturamento).', 'error');
243	      return;
244	    }
245	    setSaving(true);
246	    const ok = await onSave(parsed);
247	    setSaving(false);
248	    if (ok) {
249	      addToast('Faturamento salvo!', 'success');
250	      setEditing(false);
251	      setInputValue('');
252	    } else {
253	      addToast('Erro ao salvar o faturamento. Tente novamente.', 'error');
254	    }
255	  }
256	
257	  if (loading) {
258	    return (
259	      <div className="bg-white border-2 border-black rounded-2xl p-6 animate-pulse space-y-4">
260	        <div className="h-6 bg-gray-200 rounded-xl w-1/2" />
261	        <div className="h-4 bg-gray-200 rounded-xl w-full" />
262	      </div>
263	    );
264	  }
265	
266	  return (
267	    <div className="bg-white border-2 border-black rounded-2xl p-6 shadow-[6px_6px_0px_0px_rgba(0,0,0,1)]">
268	      <div className="flex items-center justify-between mb-4">
269	        <div className="flex items-center gap-2">
270	          <TrendingDown size={20} strokeWidth={3} />
271	          <h2 className="text-xl font-black uppercase">Faturamento do Mes</h2>
272	        </div>
273	        <button
274	          onClick={() => {
275	            setEditing((e) => !e);
276	            setInputValue(monthlyRevenueAmount != null ? String(monthlyRevenueAmount) : '');
277	          }}
278	          className="text-sm font-black uppercase px-4 py-2 rounded-xl border-2 border-black hover:bg-black hover:text-white transition-colors"
279	          aria-label={editing ? 'Cancelar edicao do faturamento' : 'Informar faturamento do mes'}
280	        >
281	          {editing ? 'Cancelar' : monthlyRevenueAmount != null ? 'Atualizar' : 'Informar'}
282	        </button>
283	      </div>
284	
285	      {editing ? (
286	        <div className="space-y-3">
287	          <label htmlFor="revenueInput" className="block text-sm font-black uppercase text-gray-600">
288	            Faturamento bruto do mes (R$)
289	          </label>
290	          <input
291	            id="revenueInput"
292	            type="number"
293	            min="0"
294	            step="0.01"
295	            value={inputValue}
296	            onChange={(e) => setInputValue(e.target.value)}
297	            placeholder="Ex: 50000,00"
298	            className="w-full border-2 border-black rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-primary text-lg font-bold tabular-nums"
299	          />
300	          <p className="text-xs text-gray-500 flex items-center gap-1">
301	            <Info size={12} />
302	            Usado para calcular custo de freelas como % do faturamento. Nao compartilhado externamente.
303	          </p>
304	          <button
305	            onClick={handleSave}
306	            disabled={saving || inputValue === ''}
307	            className="w-full bg-black hover:bg-primary text-white px-6 py-3 rounded-xl font-black uppercase transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
308	          >
309	            {saving ? 'Salvando...' : 'Salvar Faturamento'}
310	          </button>
311	        </div>
312	      ) : monthlyRevenueAmount != null ? (
313	        <div>
314	          <p className="text-xs font-bold uppercase text-gray-500">Faturamento declarado</p>
315	          <p className="text-3xl font-black tabular-nums text-blue-600">{formatBRL(monthlyRevenueAmount)}</p>
316	          <p className="text-xs text-gray-500 mt-1">Destrava o indicador custo-%-faturamento no painel abaixo.</p>
317	        </div>
318	      ) : (
319	        <div className="bg-gray-50 border-2 border-dashed border-gray-300 rounded-xl p-4 text-center">
320	          <p className="text-sm text-gray-500 font-bold">Nenhum faturamento informado.</p>
321	          <p className="text-xs text-blue-600 mt-1 font-bold">Informe para desbloquear o indicador de custo-%-faturamento.</p>
322	        </div>
323	      )}
324	    </div>
325	  );
326	}
327	
328	// ---------------------------------------------------------------------------
329	// Subcomponente: SkeletonBI
330	// ---------------------------------------------------------------------------
331	
332	function SkeletonBI() {
333	  return (
334	    <div className="space-y-6 animate-pulse">
335	      {[...Array(4)].map((_, i) => (
336	        <div key={i} className="bg-white border-2 border-black rounded-2xl p-6 space-y-4">
337	          <div className="h-6 bg-gray-200 rounded-xl w-1/3" />
338	          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
339	            <div className="h-16 bg-gray-200 rounded-xl" />
340	            <div className="h-16 bg-gray-200 rounded-xl" />
341	          </div>
342	          <div className="space-y-3">
343	            {[...Array(3)].map((_, j) => (
344	              <div key={j} className="h-14 bg-gray-200 rounded-xl" />
345	            ))}
346	          </div>
347	        </div>
348	      ))}
349	    </div>
350	  );
351	}
352	
353	// ---------------------------------------------------------------------------
354	// Pagina principal
355	// ---------------------------------------------------------------------------
356	
357	type PeriodKey = 'current' | 'previous';
358	
359	export default function CompanyFinancial() {
360	  const [periodKey, setPeriodKey] = useState<PeriodKey>('current');
361	  const [showSpendWorkerAll, setShowSpendWorkerAll] = useState(false);
362	
363	  const period: BIPeriod = periodKey === 'current' ? currentMonthPeriod() : previousMonthPeriod();
364	
365	  const {
366	    spendLimit,
367	    monthlyRevenue,
368	    loading: limitLoading,
369	    upsertSpendLimit,
370	    upsertMonthlyRevenue,
371	  } = useSpendLimit();
372	
373	  const {
374	    data,
375	    loading: biLoading,
376	    error: biError,
377	    refresh: refreshBI,
378	  } = useFinancialBI(period);
379	
380	  const accumulatedSpend = data?.accumulatedSpend.totalAmount ?? 0;
381	  const spendByWorker = data?.spendByWorker ?? [];
382	  const costRatio = data?.costRatio;
383	  const noShowCost = data?.noShowCost;
384	  const concentrationFlags = data?.concentrationFlags ?? [];
385	
386	  const WORKER_PREVIEW = 5;
387	  const workersToShow = showSpendWorkerAll ? spendByWorker : spendByWorker.slice(0, WORKER_PREVIEW);
388	  const flaggedWorkers = concentrationFlags.filter((f) => f.flagged);
389	
390	  async function handleSaveLimit(amount: number, thresholds: number[]): Promise<boolean> {
391	    const ok = await upsertSpendLimit({ amount, alertThresholds: thresholds });
392	    if (ok) refreshBI();
393	    return ok;
394	  }
395	
396	  async function handleSaveRevenue(amount: number): Promise<boolean> {
397	    const ok = await upsertMonthlyRevenue(amount);
398	    if (ok) refreshBI();
399	    return ok;
400	  }
401	
402	  return (
403	    <div className="flex flex-col gap-8 pb-20 md:pb-12 font-sans text-accent max-w-4xl mx-auto">
404	
405	      {/* Header */}
406	      <header>
407	        <h1 className="text-4xl font-black uppercase tracking-tighter mb-2">Financeiro</h1>
408	        <p className="text-gray-500 text-sm">Controle de gasto, faturamento e indicadores de freelas.</p>
409	      </header>
410	
411	      {/* Seletor de periodo */}
412	      <div className="flex gap-3">
413	        {(['current', 'previous'] as PeriodKey[]).map((key) => {
414	          const p = key === 'current' ? currentMonthPeriod() : previousMonthPeriod();
415	          const isActive = periodKey === key;
416	          return (
417	            <button
418	              key={key}
419	              onClick={() => setPeriodKey(key)}
420	              className={`px-5 py-2.5 rounded-xl border-2 font-black uppercase text-sm transition-all
421	                ${isActive
422	                  ? 'bg-black text-white border-black shadow-[4px_4px_0px_0px_rgba(0,166,81,1)]'
423	                  : 'bg-white text-gray-500 border-black hover:bg-gray-100'
424	                }`}
425	            >
426	              {periodLabel(p)}
427	            </button>
428	          );
429	        })}
430	      </div>
431	
432	      {/* Teto + Faturamento */}
433	      <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
434	        <SpendLimitCard
435	          spendLimitAmount={spendLimit?.amount ?? null}
436	          accumulatedSpend={accumulatedSpend}
437	          loading={limitLoading}
438	          onSave={handleSaveLimit}
439	        />
440	        <RevenueCard
441	          monthlyRevenueAmount={monthlyRevenue?.amount ?? null}
442	          loading={limitLoading}
443	          onSave={handleSaveRevenue}
444	        />
445	      </div>
446	
447	      {/* BI Section */}
448	      {biLoading ? (
449	        <SkeletonBI />
450	      ) : biError ? (
451	        <div className="bg-red-50 border-2 border-red-200 rounded-2xl p-6 text-center">
452	          <p className="font-black text-red-600 uppercase text-sm">{biError}</p>
453	          <button
454	            onClick={refreshBI}
455	            className="mt-3 px-6 py-2 rounded-xl border-2 border-black font-black uppercase text-sm hover:bg-black hover:text-white transition-colors"
456	          >
457	            Tentar novamente
458	          </button>
459	        </div>
460	      ) : !data || (accumulatedSpend === 0 && spendByWorker.length === 0) ? (
461	        <div className="bg-white border-2 border-black rounded-2xl p-10 text-center shadow-[6px_6px_0px_0px_rgba(0,0,0,1)]">
462	          <BarChart2 size={40} className="mx-auto mb-4 text-gray-300" />
463	          <p className="font-black text-gray-500 uppercase text-sm">Nenhum dado no periodo selecionado.</p>
464	          <p className="text-xs text-gray-400 mt-1">Os indicadores aparecem conforme os turnos sao concluidos.</p>
465	        </div>
466	      ) : (
467	        <div className="space-y-6">
468	
469	          {/* BI-3: Ratio custo/hora + custo-%-faturamento */}
470	          {costRatio && (
471	            <section className="bg-white border-2 border-black rounded-2xl p-6 shadow-[6px_6px_0px_0px_rgba(0,0,0,1)]">
472	              <div className="flex items-center gap-2 mb-5">
473	                <BarChart2 size={20} strokeWidth={3} />
474	                <h2 className="text-xl font-black uppercase">Indicadores de Custo</h2>
475	              </div>
476	
477	              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
478	                {/* Custo total */}
479	                <div className="bg-gray-50 border-2 border-black rounded-xl p-4">
480	                  <p className="text-xs font-black uppercase text-gray-500 mb-1">Custo Total</p>
481	                  <p className="text-2xl font-black tabular-nums">{formatBRL(costRatio.totalCost)}</p>
482	                  <p className="text-xs text-gray-400 mt-1">{costRatio.totalHours > 0 ? `${formatHours(costRatio.totalHours)} de trabalho` : 'Sem horas registradas'}</p>
483	                </div>
484	
485	                {/* Custo por hora */}
486	                <div className="bg-gray-50 border-2 border-black rounded-xl p-4">
487	                  <p className="text-xs font-black uppercase text-gray-500 mb-1">Custo / Hora</p>
488	                  {costRatio.costPerHour != null ? (
489	                    <p className="text-2xl font-black tabular-nums">{formatBRL(costRatio.costPerHour)}<span className="text-sm font-bold">/h</span></p>
490	                  ) : (
491	                    <p className="text-sm text-gray-400 font-bold">—</p>
492	                  )}
493	                  <p className="text-xs text-gray-400 mt-1">Media no periodo</p>
494	                </div>
495	
496	                {/* Custo % faturamento */}
497	                <div className={`border-2 rounded-xl p-4 ${costRatio.costPercentRevenue != null ? 'bg-blue-50 border-blue-200' : 'bg-gray-50 border-dashed border-gray-300'}`}>
498	                  <p className="text-xs font-black uppercase text-gray-500 mb-1">Custo % Faturamento</p>
499	                  {costRatio.costPercentRevenue != null ? (
500	                    <>
501	                      <p className="text-2xl font-black tabular-nums text-blue-600">{formatPercent(costRatio.costPercentRevenue)}</p>
502	                      <p className="text-xs text-gray-400 mt-1">do faturamento declarado</p>
503	                    </>
504	                  ) : (
505	                    <div>
506	                      <p className="text-sm text-gray-400 font-bold">Bloqueado</p>
507	                      <p className="text-xs text-blue-600 mt-1 font-bold">Informe o faturamento acima para desbloquear.</p>
508	                    </div>
509	                  )}
510	                </div>
511	              </div>
512	            </section>
513	          )}
514	
515	          {/* BI-2: Gasto por freela */}
516	          {spendByWorker.length > 0 && (
517	            <section className="bg-white border-2 border-black rounded-2xl p-6 shadow-[6px_6px_0px_0px_rgba(0,0,0,1)]">
518	              <div className="flex items-center justify-between mb-5">
519	                <div className="flex items-center gap-2">
520	                  <Users size={20} strokeWidth={3} />
521	                  <h2 className="text-xl font-black uppercase">Gasto por Freela</h2>
522	                </div>
523	                <span className="text-xs font-bold bg-gray-100 text-gray-600 px-2 py-1 rounded-full border-2 border-black">
524	                  {spendByWorker.length} freela{spendByWorker.length !== 1 ? 's' : ''}
525	                </span>
526	              </div>
527	
528	              <div id="spend-worker-list" className="space-y-3">
